contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr) public payable {
        require(logAddr != address(0), "log address must be nonzero");
        bool setReverted;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setReverted = true;
        } else {
            setReverted = false;
        }

        bool initReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        assert(!setReverted && !initReverted);
    }

    receive() external payable {}
}

